// Writes public/emoji.json, the reply box's whole emoji set with the words it's searched by (public/js/emoji.js),
// from emojibase-data (MIT; its names and keywords are Unicode CLDR's): a dev dependency, so the file is committed and
// regenerated by hand when the dataset moves (`node scripts/make-emoji.js`).
//   - every emoji up to MAX_VERSION (Unicode's emoji version): newer ones draw as an empty box on systems whose emoji
//     font hasn't caught up (Windows 11's is at 15.0);
//   - no skin-tone variants and no "component" group (the tones and hair pieces on their own);
//   - each emoji's words: its name, CLDR's keywords and GitHub's shortcodes, lowercase, once each ("lol", "lmao" find 😂).
// Shape: { v, groups: [{ key, name, icon, e: [[emoji, "words"], …] }] } in Unicode's order.
"use strict";

const fs = require("fs");
const path = require("path");
const data = require("emojibase-data/en/data.json");
const messages = require("emojibase-data/en/messages.json");
const github = require("emojibase-data/en/shortcodes/github.json");
const { version } = require("emojibase-data/package.json");

const MAX_VERSION = 15.0;
const ICONS = { "smileys-emotion": "😀", "people-body": "👋", "animals-nature": "🐶", "food-drink": "🍔", "travel-places": "✈️", activities: "⚽", objects: "💡", symbols: "💯", flags: "🏁" };

const groups = messages.groups
  .filter((g) => g.key !== "component")
  .sort((a, b) => a.order - b.order)
  .map((g) => ({ key: g.key, order: g.order, name: g.message[0].toUpperCase() + g.message.slice(1), icon: ICONS[g.key], e: [] }));
const byOrder = new Map(groups.map((g) => [g.order, g]));

data
  .filter((e) => e.emoji && e.version <= MAX_VERSION && byOrder.has(e.group))
  .sort((a, b) => a.order - b.order)
  .forEach((e) => {
    const codes = [].concat(github[e.hexcode] || []).map((c) => c.replace(/_/g, " "));
    const words = [...new Set([e.label, ...(e.tags || []), ...codes].join(" ").toLowerCase().split(/\s+/).filter(Boolean))];
    byOrder.get(e.group).e.push([e.emoji, words.join(" ")]);
  });

const out = { v: version, groups: groups.map(({ key, name, icon, e }) => ({ key, name, icon, e })) };
const file = path.join(__dirname, "..", "public", "emoji.json");
fs.writeFileSync(file, JSON.stringify(out));
const n = out.groups.reduce((s, g) => s + g.e.length, 0);
console.log(`public/emoji.json: ${n} emoji in ${out.groups.length} groups, ${Math.round(fs.statSync(file).size / 1024)} KB (emojibase-data ${version})`);
